    for value in A:
        x = value
        factors = {}
        d = 2
        while d * d <= x:
            while x % d == 0:
                factors[d] = factors.get(d, 0) + 1
                x //= d
            d += 1
        if x > 1:
            factors[x] = factors.get(x, 0) + 1
        factorized.append(factors)
        primes.update(factors)

    answer = 1
    for p in primes:
        exponents = [f.get(p, 0) for f in factorized]
        bound = sum(exponents)
        powers = [1] * (bound + 1)
        for h in range(1, bound + 1):
            powers[h] = powers[h - 1] * p % MOD

        # f[h]: paths ending at height h that have not visited 0;
        # g[h]: paths ending at height h that have visited 0.
        f = powers[:]
        f[0] = 0
        g = [0] * (bound + 1)
        g[0] = 1

        for e in exponents:
            nf = [0] * (bound + 1)
            ng = [0] * (bound + 1)
            deltas = (0,) if e == 0 else (-e, e)
            for h in range(bound + 1):
                fv, gv = f[h], g[h]
                if fv == 0 and gv == 0:
                    continue
                for delta in deltas:
                    nh = h + delta
                    if 0 <= nh <= bound:
                        weighted = powers[nh]
                        if nh == 0:
                            ng[0] = (ng[0] + (fv + gv) * weighted) % MOD
                        else:
                            nf[nh] = (nf[nh] + fv * weighted) % MOD
                            ng[nh] = (ng[nh] + gv * weighted) % MOD
            f, g = nf, ng

        answer = answer * (sum(g) % MOD) % MOD

    print(answer)

