class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]
        for idx, (x, y) in enumerate(conflictingPairs):
            a, b = (x, y) if x < y else (y, x)
            events[b].append((a, idx))

        # The two largest left endpoints among all pairs whose right
        # endpoint has appeared so far. Keep entries (left endpoint, index)
        # so equal endpoints are counted separately.
        first = (-1, -1)
        second = (-1, -1)
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for item in events[right]:
                if item[0] > first[0]:
                    second, first = first, item
                elif item[0] > second[0]:
                    second = item

            largest = max(0, first[0])
            total += right - largest

            if first[1] != -1:
                gains[first[1]] += first[0] - max(0, second[0])

        return total + max(gains)

