class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)

        def steps(x):
            count = 0
            while x != 1:
                x = x.bit_count()
                count += 1
            return count

        # For a number with c set bits, one operation produces c.
        good = [False] * (m + 1)
        for c in range(1, m + 1):
            good[c] = 1 + steps(c) <= k

        # Binomial coefficients modulo MOD.
        comb = [[0] * (m + 1) for _ in range(m + 1)]
        for i in range(m + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # Walk the bound from left to right. At each 1, fix it to 0 and
        # count valid completions of each allowed total popcount.
        ans = 0
        used = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = m - i - 1
                for c in range(1, m + 1):
                    if good[c]:
                        need = c - used
                        if 0 <= need <= remaining:
                            ans += comb[remaining][need]
                used += 1

        return ans % MOD

