    if not data:
        return
    n = int(data[0])
    graph = data[1:]
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]

    for i, row in enumerate(graph):
        for j, ch in enumerate(row):
            if ch != b'-':
                c = ch[0] - 97
                outgoing[i][c].append(j)
                incoming[j][c].append(i)

    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    heap = []
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))
        for c in range(26):
            for j in outgoing[i][c]:
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    heapq.heappush(heap, (1, i, j))

    while heap:
        value, u, v = heapq.heappop(heap)
        if value != dist[u][v]:
            continue
        new_value = value + 2
        for c in range(26):
            ins = incoming[u][c]
            outs = outgoing[v][c]
            if not ins or not outs:
                continue
            for x in ins:
                row = dist[x]
                if new_value >= max(row):
                    continue
                for y in outs:
                    if new_value < row[y]:
                        row[y] = new_value
                        heapq.heappush(heap, (new_value, x, y))

    result = []
    for row in dist:
        result.append(' '.join(str(x if x < inf else -1) for x in row))
    sys.stdout.write('\n'.join(result))

