import sys, random

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]; A=data[1:]
    # The crease sequence is determined by the two bits surrounding the
    # least significant set bit. Search representative offsets from its
    # long dyadic structure.
    def score(i):
        s=0
        for a in A:
            x=i+a
            if x and ((x >> ((x & -x).bit_length()-1)) & 3)==1:
                s+=1
        return s
    lim=(1<<100)-A[-1]-1
    candidates=set(range(1,min(lim,200000)+1))
    for a in A:
        for k in range(0,61):
            p=1<<k
            for v in (p-a, 2*p-a, 3*p-a, -a):
                for d in range(-2,3):
                    x=v+d
                    if 1<=x<=lim: candidates.add(x)
    # deterministic pseudo-random probes over the available range
    rng=random.Random(1)
    for _ in range(20000):
        x=rng.randrange(1,lim+1)
        candidates.add(x)
    ans=0
    for i in candidates:
        ans=max(ans,score(i))
    print(ans)
